import { CommonModule } from '@angular/common';
import { Component, EventEmitter, Input, Output } from '@angular/core';
import { CheckboxComponent, CheckboxState, CheckboxValue } from '../checkbox/checkbox.component';

export type CheckboxGroupDirection = 'inline' | 'stacked';
export type CheckboxGroupState = 'default' | 'invalid' | 'disabled';

export interface CheckboxGroupOption {
  label: string;
  value: string;
  disabled?: boolean;
}

let nextCheckboxGroupId = 0;

/** A labelled set of independent checkbox options in an inline or stacked layout. */
@Component({
  selector: 'dds-checkbox-group',
  standalone: true,
  imports: [CommonModule, CheckboxComponent],
  templateUrl: './checkbox-group.component.html',
  styleUrl: './checkbox-group.component.css',
})
export class CheckboxGroupComponent {
  @Input() groupId = `dds-checkbox-group-${nextCheckboxGroupId++}`;
  @Input() label = 'Label';
  @Input() options: CheckboxGroupOption[] = [
    { label: 'Option 1', value: 'option-1' },
    { label: 'Option 2', value: 'option-2' },
    { label: 'Option 3', value: 'option-3' },
    { label: 'Option 4', value: 'option-4' },
  ];
  @Input() selectedValues: string[] = [];
  @Input() direction: CheckboxGroupDirection = 'inline';
  @Input() state: CheckboxGroupState = 'default';
  @Input() required = true;
  @Input() showLabel = true;
  @Input() helperText = 'Select all options that apply.';
  @Input() showHelperText = false;
  @Input() errorMessage = 'Select at least one option.';

  @Output() selectedValuesChange = new EventEmitter<string[]>();

  get supportingTextId(): string {
    return `${this.groupId}-${this.state === 'invalid' ? 'error' : 'helper'}`;
  }

  get describedBy(): string | undefined {
    return this.state === 'invalid' || this.showHelperText ? this.supportingTextId : undefined;
  }

  optionState(option: CheckboxGroupOption): CheckboxState {
    if (this.state === 'disabled' || option.disabled) return 'disabled';
    if (this.state === 'invalid') return 'invalid';
    return 'default';
  }

  optionValue(option: CheckboxGroupOption): CheckboxValue {
    return this.selectedValues.includes(option.value) ? 'checked' : 'unchecked';
  }

  toggle(option: CheckboxGroupOption, value: CheckboxValue): void {
    const selected = new Set(this.selectedValues);
    value === 'checked' ? selected.add(option.value) : selected.delete(option.value);
    this.selectedValues = [...selected];
    this.selectedValuesChange.emit(this.selectedValues);
  }
}

import { CommonModule } from '@angular/common';
import { Component, EventEmitter, Input, Output } from '@angular/core';
import { RadioComponent, RadioState } from '../radio/radio.component';

export type RadioGroupDirection = 'inline' | 'stacked';
export type RadioGroupState = 'default' | 'invalid' | 'disabled';

export interface RadioOption {
  label: string;
  value: string;
  disabled?: boolean;
}

let nextRadioGroupId = 0;

/** A labelled set of mutually exclusive radio options in an inline or stacked layout. */
@Component({
  selector: 'dds-radio-group',
  standalone: true,
  imports: [CommonModule, RadioComponent],
  templateUrl: './radio-group.component.html',
  styleUrl: './radio-group.component.css',
})
export class RadioGroupComponent {
  @Input() groupId = `dds-radio-group-${nextRadioGroupId++}`;
  @Input() label = 'Label text';
  @Input() options: RadioOption[] = [
    { label: 'Option 1', value: 'option-1' },
    { label: 'Option 2', value: 'option-2' },
    { label: 'Option 3', value: 'option-3' },
    { label: 'Option 4', value: 'option-4' },
  ];
  @Input() selectedValue = 'option-1';
  @Input() direction: RadioGroupDirection = 'inline';
  @Input() state: RadioGroupState = 'default';
  @Input() required = true;
  @Input() showLabel = true;
  @Input() errorMessage = 'Select an option to continue.';

  @Output() selectedValueChange = new EventEmitter<string>();

  get errorId(): string {
    return `${this.groupId}-error`;
  }

  optionState(option: RadioOption): RadioState {
    if (this.state === 'disabled' || option.disabled) return 'disabled';
    if (this.state === 'invalid') return 'invalid';
    return 'default';
  }

  select(value: string): void {
    this.selectedValue = value;
    this.selectedValueChange.emit(value);
  }
}

import { CommonModule } from '@angular/common';
import { Component, EventEmitter, Input, Output } from '@angular/core';
import { DdsIconName, IconComponent } from '../icon/icon.component';

export interface SidebarNavItem {
  id: string;
  label: string;
  href?: string;
  icon?: DdsIconName;
  disabled?: boolean;
  children?: SidebarNavItem[];
}

/** A persistent application sidebar with one level of expandable navigation groups. */
@Component({
  selector: 'dds-sidebar-nav',
  standalone: true,
  imports: [CommonModule, IconComponent],
  templateUrl: './sidebar-nav.component.html',
  styleUrl: './sidebar-nav.component.css',
})
export class SidebarNavComponent {
  @Input() title = 'DDS Enterprise';
  @Input() footer = 'Version 1.0.0';
  @Input() ariaLabel = 'Primary navigation';
  @Input() items: SidebarNavItem[] = [];
  @Input() activeItemId?: string;
  @Input() expandedIds: string[] = [];

  @Output() activeItemIdChange = new EventEmitter<string>();
  @Output() expandedIdsChange = new EventEmitter<string[]>();
  @Output() itemSelect = new EventEmitter<SidebarNavItem>();

  isExpanded(item: SidebarNavItem): boolean {
    return this.expandedIds.includes(item.id);
  }

  isActive(item: SidebarNavItem): boolean {
    return this.activeItemId === item.id;
  }

  hasActiveChild(item: SidebarNavItem): boolean {
    return Boolean(item.children?.some((child) => child.id === this.activeItemId));
  }

  submenuId(item: SidebarNavItem): string {
    return `dds-sidebar-nav-${item.id}-submenu`;
  }

  toggle(item: SidebarNavItem): void {
    if (item.disabled) return;

    const expanded = this.isExpanded(item);
    this.expandedIds = expanded
      ? this.expandedIds.filter((id) => id !== item.id)
      : [...this.expandedIds, item.id];
    this.expandedIdsChange.emit(this.expandedIds);
  }

  select(item: SidebarNavItem, event?: Event): void {
    if (item.disabled) {
      event?.preventDefault();
      return;
    }

    this.activeItemId = item.id;
    this.activeItemIdChange.emit(item.id);
    this.itemSelect.emit(item);
  }
}

