:host {
  display: inline-block;
}

.dds-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-2);
  border: 1px solid;
  border-radius: var(--radius-sm);
  font-family: var(--font-family-primary);
  font-weight: var(--font-weight-medium);
  letter-spacing: var(--space-none);
  cursor: pointer;
  position: relative;
  outline: none;
  transition:
    background-color 0.2s ease-in-out,
    border-color 0.2s ease-in-out,
    box-shadow 0.2s ease-in-out;
}

.dds-button:disabled {
  background-color: var(--btn-colour-primary-disabled);
  border-color: var(--btn-colour-primary-disabled);
  cursor: not-allowed;
  color: var(--text-colour-disabled);
}

.dds-button--large {
  height: 48px;
  min-height: 48px;
  padding: 12px 24px;
  font-size: var(--font-size-md);
  line-height: 24px;
}

.dds-button--medium {
  height: 40px;
  min-height: 40px;
  padding: 8px 16px;
  font-size: var(--font-size-sm);
  line-height: 20px;
}

.dds-button--small {
  height: 32px;
  min-height: 32px;
  padding: 4px 12px;
  font-size: var(--font-size-xs);
  line-height: 16px;
}

/* Primary Button */
.dds-button--primary {
  background-color: var(--btn-colour-primary);
  border-color: var(--btn-colour-primary);
  color: var(--text-colour-inverse);
}

.dds-button--primary:hover:not(:disabled),
.dds-button--state-hover.dds-button--primary:not(:disabled) {
  background-color: var(--btn-colour-primary-hover);
  border-color: var(--btn-colour-primary-hover);
}

.dds-button--primary:focus,
.dds-button--primary:focus-visible,
.dds-button--primary:active,
.dds-button--primary:hover:active,
.dds-button--state-focused.dds-button--primary:not(:disabled) {
  background-color: var(--btn-colour-primary);
  border-color: var(--colour-neutral-white);
  box-shadow: var(--btn-primary-focus-ring);
}

/* Secondary Button */
.dds-button--secondary {
  background-color: var(--btn-colour-secondary);
  border-color: var(--border-colour-default);
  color: var(--text-colour-default);
}

.dds-button--secondary:hover:not(:disabled),
.dds-button--state-hover.dds-button--secondary:not(:disabled) {
  background-color: var(--btn-colour-secondary-hover);
  border-color: var(--border-colour-default);
}

.dds-button--secondary:focus,
.dds-button--secondary:focus-visible,
.dds-button--secondary:active,
.dds-button--secondary:hover:active,
.dds-button--state-focused.dds-button--secondary:not(:disabled) {
  background-color: var(--btn-colour-secondary);
  border-color: var(--colour-neutral-white);
  box-shadow: var(--btn-primary-focus-ring);
}

/* Ghost Button */
.dds-button--ghost {
  background-color: var(--btn-colour-ghost);
  border: none;
  color: var(--text-colour-accent);
}

.dds-button--ghost:hover:not(:disabled),
.dds-button--state-hover.dds-button--ghost:not(:disabled) {
  background-color: var(--btn-colour-ghost-hover);
}

.dds-button--ghost:focus,
.dds-button--ghost:focus-visible,
.dds-button--ghost:active,
.dds-button--ghost:hover:active,
.dds-button--state-focused.dds-button--ghost:not(:disabled) {
  background-color: var(--btn-colour-ghost-hover);
  border-color: var(--border-colour-default);
  box-shadow: var(--btn-primary-focus-ring);
}

.dds-button--ghost .dds-button__label {
  display: block;
  height: 100%;
  position: relative;
}

.dds-button--ghost .dds-button__label::after {
  background-color: var(--bg-colour-accent);
  content: '';
  display: block;
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  width: 100%;
  height: 1px;
}

/* Danger Button */

.dds-button--danger.dds-button--primary {
  background-color: var(--btn-colour-danger);
  border-color: var(--btn-colour-danger);
}

.dds-button--danger.dds-button--primary:hover:not(:disabled),
.dds-button--danger.dds-button--state-hover.dds-button--primary:not(:disabled) {
  background-color: var(--btn-colour-danger-hover);
  border-color: var(--btn-colour-danger-hover);
}

.dds-button--danger.dds-button--primary:focus,
.dds-button--danger.dds-button--primary:focus-visible,
.dds-button--danger.dds-button--primary:active,
.dds-button--danger.dds-button--primary:hover:active,
