styleUrlsData.data:
:host {
  display: block;
  color: var(--text-colour-default);
  background: var(--bg-colour-default);
}
* {
  box-sizing: border-box;
}
.typography-page {
  width: min(100%, 1180px);
  margin: 0 auto;
  padding: 64px 40px 96px;
}
.page-header {
  max-width: 760px;
  margin-bottom: 48px;
}
.eyebrow,
.section-kicker {
  margin: 0 0 8px;
  color: var(--text-colour-accent);
  font-size: 12px;
  line-height: 16px;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}
h1 {
  margin: 0;
  font-size: 48px;
  line-height: 58px;
  font-weight: 600;
  letter-spacing: -0.02em;
}
.page-intro {
  max-width: 680px;
  margin: 16px 0 0;
  color: var(--text-colour-secondary);
  font-size: 18px;
  line-height: 28px;
}
.font-overview {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  gap: 24px;
  align-items: center;
  margin-bottom: 72px;
  padding: 28px 32px;
  border: 1px solid var(--border-colour-subtle);
  border-radius: 12px;
  background: var(--bg-colour-white);
  box-shadow: 0 1px 2px rgb(0 0 0 / 4%);
}
.font-monogram {
  display: grid;
  place-items: center;
  width: 88px;
  height: 88px;
  border-radius: 12px;
  color: var(--text-colour-accent);
  background: var(--bg-colour-info-muted);
  font-size: 40px;
  line-height: 1;
  font-weight: 600;
}
.font-details h2 {
  margin: 0;
  font-size: 28px;
  line-height: 36px;
  font-weight: 600;
}
.font-details > p:last-child {
  max-width: 560px;
  margin: 4px 0 0;
  color: var(--text-colour-secondary);
  font-size: 14px;
  line-height: 22px;
}
.font-actions {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 10px;
}
.font-actions > span {
  color: var(--text-colour-tertiary);
  font-size: 12px;
  line-height: 16px;
}
.font-actions a {
  display: inline-flex;
  gap: 6px;
  color: var(--text-colour-accent);
  font-size: 14px;
  line-height: 20px;
  font-weight: 500;
  text-underline-offset: 3px;
}
.documentation-section + .documentation-section {
  margin-top: 80px;
}
.section-intro {
  display: grid;
  grid-template-columns: minmax(220px, 0.7fr) minmax(320px, 1fr);
  gap: 48px;
  align-items: end;
  margin-bottom: 28px;
}
.section-intro h2 {
  margin: 0;
  font-size: 32px;
  line-height: 40px;
  font-weight: 600;
  letter-spacing: -0.01em;
}
.section-intro > p {
  max-width: 620px;
  margin: 0;
  color: var(--text-colour-secondary);
  font-size: 14px;
  line-height: 22px;
}
.scale-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 24px;
  align-items: start;
}
.content-scales {
  display: grid;
  gap: 24px;
}
.scale-card {
  min-width: 0;
  overflow: hidden;
  border: 1px solid var(--border-colour-subtle);
  border-radius: 12px;
  background: var(--bg-colour-white);
  box-shadow: 0 1px 2px rgb(0 0 0 / 4%);
}
.scale-card > header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  min-height: 64px;
  padding: 16px 20px;
  border-bottom: 1px solid var(--border-colour-subtle);
}
.scale-card > header h3 {
  margin: 0;
  font-size: 16px;
  line-height: 24px;
  font-weight: 600;
}
.scale-card > header p {
  margin: 0;
  color: var(--text-colour-tertiary);
  font-size: 12px;
  line-height: 16px;
}
.platform-badge {
  flex: none;
  padding: 3px 8px;
  border-radius: 9999px;
  color: var(--text-colour-info);
  background: var(--bg-colour-info-muted);
  font-size: 11px;
  line-height: 16px;
  font-weight: 500;
}
.type-table {
  width: 100%;
}
.table-row {
  display: grid;
  grid-template-columns: minmax(128px, 1.35fr) minmax(100px, 1fr) 64px 64px minmax(140px, 1.25fr);
  align-items: center;
  min-height: 56px;
  padding: 8px 20px;
}
.scale-grid .table-row {
  grid-template-columns: minmax(118px, 1.2fr) minmax(92px, 1fr) 58px 52px;
}
.scale-grid .table-row > span:last-child {
  display: none;
}
.table-row + .table-row {
  border-top: 1px solid var(--border-colour-subtle);
}
.table-row > span {
  min-width: 0;
  padding-right: 12px;
  color: var(--text-colour-secondary);
  font-size: 13px;
  line-height: 18px;
  overflow-wrap: anywhere;
}
.table-row > span:last-child {
  padding-right: 0;
}
.table-header {
  min-height: 40px;
  background: var(--bg-colour-default);
}
.table-header > span {
  color: var(--text-colour-tertiary);
  font-size: 10px;
  line-height: 14px;
  font-weight: 600;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}
.style-sample {
  color: var(--text-colour-default) !important;
  font-weight: 600;
}
.heading-desktop-1 {
  font-size: 32px !important;
  line-height: 40px !important;
}
.heading-desktop-2 {
  font-size: 28px !important;
  line-height: 36px !important;
}
.heading-desktop-3,
.heading-mobile-1 {
  font-size: 24px !important;
  line-height: 32px !important;
}
.heading-mobile-2 {
  font-size: 22px !important;
  line-height: 30px !important;
}
.heading-desktop-4,
.heading-mobile-3 {
  font-size: 20px !important;
  line-height: 28px !important;
}
.heading-desktop-5 {
  font-size: 18px !important;
  line-height: 24px !important;
}
.heading-mobile-4 {
  font-size: 18px !important;
  line-height: 26px !important;
}
.heading-desktop-6,
.heading-mobile-5 {
  font-size: 16px !important;
  line-height: 24px !important;
}
.heading-mobile-6 {
  font-size: 14px !important;
  line-height: 20px !important;
}
.body-xl {
  font-size: 18px !important;
  line-height: 24px !important;
  font-weight: 400;
}
.body-lg,
.label-lg {
  font-size: 16px !important;
  line-height: 24px !important;
}
.body-default {
  font-size: 14px !important;
  line-height: 22px !important;
  font-weight: 400;
}
.body-sm {
  font-size: 12px !important;
  line-height: 18px !important;
  font-weight: 400;
}
.body-xs {
  font-size: 10px !important;
  line-height: 16px !important;
  font-weight: 400;
}
.label-lg,
.label-md,
.label-sm,
.label-xs {
  font-weight: 500;
}
.label-md-600,
.label-sm-600 {
  font-weight: 600;
}
.label-md,
.label-md-600,
.label-md-400 {
  font-size: 14px !important;
  line-height: 20px !important;
}
.label-sm,
.label-sm-600,
.label-sm-400 {
  font-size: 12px !important;
  line-height: 16px !important;
}
.label-xs {
  font-size: 10px !important;
  line-height: 16px !important;
}
.label-md-400,
.label-sm-400 {
  font-weight: 400;
}
.usage-note {
  display: flex;
  gap: 16px;
  margin-top: 64px;
  padding: 20px 24px;
  border-left: 3px solid var(--border-colour-info);
  border-radius: 0 8px 8px 0;
  background: var(--bg-colour-info-muted);
}
.usage-note > div:first-child {
  display: grid;
  place-items: center;
  flex: none;
  width: 24px;
  height: 24px;
  border: 1px solid currentColor;
  border-radius: 50%;
  color: var(--text-colour-info);
  font-size: 13px;
  font-weight: 600;
}
.usage-note h2 {
  margin: 0;
  font-size: 14px;
  line-height: 20px;
  font-weight: 600;
}
.usage-note p {
  margin: 4px 0 0;
  color: var(--text-colour-secondary);
  font-size: 13px;
  line-height: 20px;
}
@media (max-width: 960px) {
  .scale-grid {
    grid-template-columns: 1fr;
  }
  .scale-grid .table-row {
    grid-template-columns: minmax(150px, 1.3fr) minmax(120px, 1fr) 80px 80px minmax(180px, 1.4fr);
  }
  .scale-grid .table-row > span:last-child {
    display: block;
  }
}
@media (max-width: 720px) {
  .typography-page {
    padding: 40px 20px 64px;
  }
  h1 {
    font-size: 40px;
    line-height: 48px;
  }
  .page-intro {
    font-size: 16px;
    line-height: 24px;
  }
  .font-overview {
    grid-template-columns: auto 1fr;
    padding: 24px;
  }
  .font-actions {
    grid-column: 2;
    align-items: flex-start;
  }
  .section-intro {
    grid-template-columns: 1fr;
    gap: 12px;
  }
  .documentation-section + .documentation-section {
    margin-top: 64px;
  }
  .type-table {
    overflow-x: auto;
  }
  .table-row,
  .scale-grid .table-row {
    grid-template-columns: 150px 120px 72px 72px minmax(180px, 1fr);
    min-width: 650px;
  }
}
@media (max-width: 480px) {
  .font-overview {
    grid-template-columns: 1fr;
  }
  .font-monogram {
    width: 72px;
    height: 72px;
    font-size: 32px;
  }
  .font-actions {
    grid-column: 1;
    align-items: flex-start;
  }
  .scale-card > header {
    align-items: flex-start;
    flex-direction: column;
    gap: 4px;
  }
}
